package com.jsh.erp.service;

import com.alibaba.fastjson.*;
import com.jsh.erp.datasource.entities.User;
import com.jsh.erp.datasource.entities.UserBusiness;
import com.jsh.erp.exception.BusinessRunTimeException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import javax.annotation.Resource;
import java.math.*;
import java.time.LocalDate;
import java.util.*;

@Service
public class FactoryOrderChangeService {
 @Resource private JdbcTemplate jdbc;
 @Resource private UserService users;
 @Resource private UserBusinessService business;
 @Resource private FactoryStockService stock;
 private void require(boolean b,String s){if(!b)throw new BusinessRunTimeException(409,s);}
 private long num(Object v){return ((Number)v).longValue();}
 private String text(JSONObject b,String k,int limit,boolean required){String v=b.getString(k);v=v==null?"":v.trim();require(v.length()<=limit&&(!required||!v.isEmpty()),"请完整填写"+k+"，且内容不能超过"+limit+"字");return v;}
 private List<Long> leaders(long tenant,boolean lock){List<String> rows=jdbc.queryForList("SELECT leader_ids FROM jsh_factory_change_config WHERE tenant_id=?"+(lock?" FOR UPDATE":""),String.class,tenant);return rows.isEmpty()?Collections.emptyList():JSON.parseArray(rows.get(0),Long.class);}
 private boolean coordinator(User u,boolean lock){List<Long> rows=jdbc.queryForList("SELECT coordinator_id FROM jsh_factory_production_config WHERE tenant_id=?"+(lock?" FOR UPDATE":""),Long.class,u.getTenantId());return !rows.isEmpty()&&u.getId().equals(rows.get(0));}
 private User actor()throws Exception{
  User u=users.getCurrentUser();require(u!=null&&u.getTenantId()!=null&&u.getTenantId()>0,"请使用业务租户账号");boolean allowed=u.getId().equals(u.getTenantId())||leaders(u.getTenantId(),false).contains(u.getId())||coordinator(u,false);
  List<Long> menus=jdbc.queryForList("SELECT id FROM jsh_function WHERE url IN('/factory/order_change','/bill/sale_order') AND enabled=1 AND IFNULL(delete_flag,'0')='0'",Long.class);
  for(UserBusiness role:business.getBasicData(u.getId().toString(),"UserRole"))for(UserBusiness f:business.getBasicData(role.getValue().replace("[","").replace("]",""),"RoleFunctions"))for(Long menu:menus)if(f.getValue()!=null&&f.getValue().contains("["+menu+"]"))allowed=true;
  require(allowed,"没有订单变更权限");return u;
 }
 public Map<String,Object> options()throws Exception{User u=actor();Map<String,Object> r=new HashMap<>();r.put("canConfigure",u.getId().equals(u.getTenantId()));r.put("isLeader",leaders(u.getTenantId(),false).contains(u.getId()));r.put("isCoordinator",coordinator(u,false));r.put("leaderIds",leaders(u.getTenantId(),false));r.put("users",jdbc.queryForList("SELECT id,username,login_name FROM jsh_user WHERE tenant_id=? AND status=0 AND IFNULL(delete_flag,'0')='0' ORDER BY id",u.getTenantId()));return r;}
 @Transactional(rollbackFor=Exception.class)
 public void configure(JSONObject b)throws Exception{
  User u=actor();require(u.getId().equals(u.getTenantId()),"仅负责人可配置订单变更审批领导");stock.lockForInventoryMutation();JSONArray input=b.getJSONArray("leaderIds");require(input!=null&&!input.isEmpty()&&input.size()<=30,"请选择1至30位领导");Set<Long> ids=new LinkedHashSet<>();for(int i=0;i<input.size();i++){Long id=input.getLong(i);require(id!=null&&ids.add(id)&&jdbc.queryForObject("SELECT COUNT(*) FROM jsh_user WHERE tenant_id=? AND id=? AND status=0 AND IFNULL(delete_flag,'0')='0'",Integer.class,u.getTenantId(),id)==1,"请选择本租户有效且不重复的领导账号");}jdbc.update("INSERT INTO jsh_factory_change_config VALUES(?,?) ON DUPLICATE KEY UPDATE leader_ids=VALUES(leader_ids)",u.getTenantId(),JSON.toJSONString(ids));audit(u,0,"configure","配置变更审批领导",ids);
 }
 private Map<String,Object> order(long id,User u,boolean lock){List<Map<String,Object>> rows=jdbc.queryForList("SELECT f.*,h.number,c.supplier customer_name FROM jsh_factory_sales_order f JOIN jsh_depot_head h ON h.id=f.head_id AND h.tenant_id=f.tenant_id LEFT JOIN jsh_supplier c ON c.id=h.organ_id AND c.tenant_id=f.tenant_id WHERE f.tenant_id=? AND f.head_id=? AND IFNULL(h.delete_flag,'0')='0'"+(lock?" FOR UPDATE":""),u.getTenantId(),id);require(!rows.isEmpty(),"订单不存在或无权访问");return rows.get(0);}
 private Map<String,Object> task(long id,User u,boolean lock){List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM jsh_factory_production_task WHERE tenant_id=? AND head_id=?"+(lock?" FOR UPDATE":""),u.getTenantId(),id);require(!rows.isEmpty(),"请先建立并安排生产任务");return rows.get(0);}
 private void eligible(Map<String,Object> order,Map<String,Object> task,User u){require("approved".equals(order.get("workflow_status"))&&"scheduled".equals(task.get("workflow_status")),"仅已审核并分配生产的订单可申请变更或取消");stock.requireNoShipment(num(order.get("head_id")),u);}
 private JSONObject snapshot(Map<String,Object> order){JSONObject r=new JSONObject();r.put("deliveryDate",order.get("delivery_date").toString().substring(0,10));r.put("requirements",order.get("requirements"));JSONArray lines=new JSONArray(),raw=JSON.parseArray(order.get("lines_json").toString());for(int i=0;i<raw.size();i++){JSONObject line=new JSONObject();line.put("lineNo",i);for(String k:Arrays.asList("id","barCode","name","brand","standard","model","quantity"))line.put(k,raw.getJSONObject(i).get(k));line.put("quantity",raw.getJSONObject(i).getBigDecimal("quantity").stripTrailingZeros());lines.add(line);}r.put("lines",lines);return r;}
 private String key(JSONObject p){return p.getIntValue("lineNo")+"|"+p.getIntValue("stageNo")+"|"+p.getIntValue("workshopNo");}
 private Map<String,BigDecimal> actual(long head,User u,boolean lock){Map<String,BigDecimal> r=new HashMap<>();for(Map<String,Object> row:jdbc.queryForList("SELECT line_no,stage_no,workshop_no,output_quantity FROM jsh_factory_production_report WHERE tenant_id=? AND head_id=?"+(lock?" FOR UPDATE":""),u.getTenantId(),head)){String k=row.get("line_no")+"|"+row.get("stage_no")+"|"+row.get("workshop_no");r.put(k,r.getOrDefault(k,BigDecimal.ZERO).add((BigDecimal)row.get("output_quantity")));}return r;}
 private Map<String,Object> source(long id,User u){Map<String,Object> o=order(id,u,false),t=task(id,u,false),r=new HashMap<>();r.put("headId",id);r.put("number",o.get("number"));r.put("customer_name",o.get("customer_name"));r.put("order",snapshot(o));r.put("orderVersion",o.get("version"));r.put("taskVersion",t.get("version"));r.put("isOwner",num(o.get("created_by"))==u.getId());JSONArray plan=JSON.parseArray(t.get("plan_json").toString());Map<String,BigDecimal> actual=actual(id,u,false);for(Object p:plan){JSONObject row=(JSONObject)p;row.put("reportedOutput",actual.getOrDefault(key(row),BigDecimal.ZERO));}r.put("plan",plan);return r;}
 public Map<String,Object> source(long id)throws Exception{return source(id,actor());}
 private Map<String,Object> paged(String select,String from,Object[] args,int page){Map<String,Object> r=new HashMap<>();r.put("total",jdbc.queryForObject("SELECT COUNT(*)"+from,Long.class,args));List<Object> v=new ArrayList<>(Arrays.asList(args));v.add((page-1)*10);r.put("rows",jdbc.queryForList(select+from+" ORDER BY 1 DESC LIMIT 10 OFFSET ?",v.toArray()));return r;}
 private void page(String k,int p){require(k.length()<=100&&p>0&&p<=100000,"查询参数无效");}
 public Map<String,Object> sources(String keyword,int page)throws Exception{User u=actor();page(keyword,page);String from=" FROM jsh_factory_sales_order f JOIN jsh_depot_head h ON h.id=f.head_id AND h.tenant_id=f.tenant_id JOIN jsh_factory_production_task t ON t.head_id=f.head_id AND t.tenant_id=f.tenant_id LEFT JOIN jsh_supplier c ON c.id=h.organ_id AND c.tenant_id=f.tenant_id WHERE f.tenant_id=? AND f.created_by=? AND f.workflow_status='approved' AND t.workflow_status='scheduled' AND IFNULL(h.delete_flag,'0')='0' AND (h.number LIKE ? OR c.supplier LIKE ?)";return paged("SELECT f.head_id,h.number,c.supplier customer_name",from,new Object[]{u.getTenantId(),u.getId(),"%"+keyword+"%","%"+keyword+"%"},page);}
 public Map<String,Object> list(String keyword,int page)throws Exception{User u=actor();page(keyword,page);String from=" FROM jsh_factory_order_change ch JOIN jsh_depot_head h ON h.id=ch.head_id AND h.tenant_id=ch.tenant_id LEFT JOIN jsh_supplier c ON c.id=h.organ_id AND c.tenant_id=ch.tenant_id WHERE ch.tenant_id=? AND (h.number LIKE ? OR c.supplier LIKE ?)";return paged("SELECT ch.id,ch.head_id,h.number,c.supplier customer_name,ch.kind,ch.workflow_status,ch.reason,ch.created_at,ch.applied_at",from,new Object[]{u.getTenantId(),"%"+keyword+"%","%"+keyword+"%"},page);}
 @Transactional(rollbackFor=Exception.class)
 public long create(JSONObject b)throws Exception{
  User u=actor();stock.lockForInventoryMutation();Long head=b.getLong("headId");require(head!=null,"请选择原订单");Map<String,Object> o=order(head,u,true),t=task(head,u,true);eligible(o,t,u);require(num(o.get("created_by"))==u.getId(),"仅原订单销售人员可发起变更");require(b.getInteger("orderVersion")!=null&&b.getInteger("orderVersion").equals(o.get("version")),"订单或预留已更新，请刷新");require(!leaders(u.getTenantId(),true).isEmpty(),"请先配置变更审批领导");require(jdbc.queryForList("SELECT id FROM jsh_factory_order_change WHERE tenant_id=? AND head_id=? AND workflow_status IN('pending','approved') FOR UPDATE",Long.class,u.getTenantId(),head).isEmpty(),"当前订单已有待处理的变更申请");
  String kind=b.getString("kind"),reason=text(b,"reason",2000,true);require(Arrays.asList("change","cancel").contains(kind),"变更类型无效");JSONObject before=snapshot(o),after=JSON.parseObject(before.toJSONString());
  if("change".equals(kind)){
   String day=text(b,"deliveryDate",10,true);try{LocalDate.parse(day);}catch(java.time.format.DateTimeParseException e){throw new BusinessRunTimeException(409,"交期格式无效");}after.put("deliveryDate",day);after.put("requirements",text(b,"requirements",4000,false));JSONArray input=b.getJSONArray("lines"),lines=after.getJSONArray("lines");require(input!=null&&input.size()==lines.size(),"不能增加、删除或更换产品明细");boolean positive=false;
   for(int i=0;i<lines.size();i++){JSONObject raw=input.getJSONObject(i);BigDecimal q=raw.getBigDecimal("quantity");require(raw.getInteger("lineNo")!=null&&raw.getIntValue("lineNo")==i&&q!=null&&q.signum()>=0&&q.scale()<=6&&q.precision()-q.scale()<=12,"产品行顺序或数量无效，数量最多6位小数");lines.getJSONObject(i).put("quantity",q.stripTrailingZeros());positive|=q.signum()>0;}require(positive,"全部数量为0请申请整单取消");require(!JSON.parseObject(before.toJSONString()).equals(JSON.parseObject(after.toJSONString())),"未修改数量、交期或客户要求");
  }
  jdbc.update("INSERT INTO jsh_factory_order_change(tenant_id,head_id,kind,workflow_status,reason,before_json,after_json,created_by,created_at) VALUES(?,?,?,'pending',?,?,?,?,NOW())",u.getTenantId(),head,kind,reason,before.toJSONString(),after.toJSONString(),u.getId());long id=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit(u,id,"submit",reason,after);return id;
 }
 private Map<String,Object> doc(long id,User u,boolean lock){List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM jsh_factory_order_change WHERE tenant_id=? AND id=?"+(lock?" FOR UPDATE":""),u.getTenantId(),id);require(!rows.isEmpty(),"变更申请不存在或无权访问");return rows.get(0);}
 public Map<String,Object> detail(long id)throws Exception{User u=actor();Map<String,Object> r=doc(id,u,false);r.put("before",JSON.parseObject(r.remove("before_json").toString()));r.put("after",JSON.parseObject(r.remove("after_json").toString()));r.put("isOwner",num(r.get("created_by"))==u.getId());r.put("source",source(num(r.get("head_id")),u));r.put("history",jdbc.queryForList("SELECT action,actor_name,comment,payload_json,created_at FROM jsh_factory_order_change_history WHERE tenant_id=? AND change_id=? ORDER BY id",u.getTenantId(),id));return r;}
 @Transactional(rollbackFor=Exception.class)
 public void action(long id,JSONObject b)throws Exception{
  User u=actor();stock.lockForInventoryMutation();Map<String,Object> ch=doc(id,u,true);long head=num(ch.get("head_id"));Map<String,Object> o=order(head,u,true),t=task(head,u,true);require(b.getInteger("version")!=null&&b.getInteger("version").equals(ch.get("version")),"申请已更新，请重新打开");String a=b.getString("action"),state=ch.get("workflow_status").toString(),comment=text(b,"comment",2000,false);
  if("withdraw".equals(a)){require("pending".equals(state)&&num(ch.get("created_by"))==u.getId()&&!comment.isEmpty(),"仅申请销售可说明原因后撤回待审申请");state="withdrawn";}
  else if("approve".equals(a)||"reject".equals(a)){
   require("pending".equals(state)&&leaders(u.getTenantId(),true).contains(u.getId()),"仅配置的任意一位领导可审批待审申请");if("reject".equals(a)){require(!comment.isEmpty(),"退回原因必填");state="rejected";}else{eligible(o,t,u);require(JSON.parseObject(snapshot(o).toJSONString()).equals(JSON.parseObject(ch.get("before_json").toString())),"订单内容已变化，请退回销售重新申请");jdbc.update("UPDATE jsh_factory_order_change SET approved_by=?,approved_at=NOW() WHERE tenant_id=? AND id=?",u.getId(),u.getTenantId(),id);state="approved";}
  }else if("apply".equals(a)){
   require("approved".equals(state)&&coordinator(u,true),"仅生产统筹可落实领导批准的变更");eligible(o,t,u);require(b.getInteger("orderVersion")!=null&&b.getInteger("orderVersion").equals(o.get("version"))&&b.getInteger("taskVersion")!=null&&b.getInteger("taskVersion").equals(t.get("version")),"订单预留或生产进度已更新，请刷新后重新核对");require(!comment.isEmpty(),"请填写统筹调整或停产说明");require(JSON.parseObject(snapshot(o).toJSONString()).equals(JSON.parseObject(ch.get("before_json").toString())),"订单内容已变化，不能直接落实");apply(ch,o,t,b,u);state="applied";
  }else throw new BusinessRunTimeException(409,"无效的变更操作");
  jdbc.update("UPDATE jsh_factory_order_change SET workflow_status=?,version=version+1 WHERE tenant_id=? AND id=?",state,u.getTenantId(),id);audit(u,id,a,comment,b);
 }
 private void apply(Map<String,Object> ch,Map<String,Object> o,Map<String,Object> t,JSONObject b,User u){
  long head=num(o.get("head_id"));boolean cancel="cancel".equals(ch.get("kind"));JSONObject after=JSON.parseObject(ch.get("after_json").toString());JSONArray oldPlan=JSON.parseArray(t.get("plan_json").toString()),plan=JSON.parseArray(oldPlan.toJSONString()),input=b.getJSONArray("plan");require(!plan.isEmpty(),"生产任务尚未排班，请先完成排班后落实变更");if(!cancel)require(input!=null&&input.size()==plan.size(),"请逐行核对现有排班的调整后累计计划量");Map<String,BigDecimal> actual=actual(head,u,true),totals=new HashMap<>();Set<String> filled=new HashSet<>();
  for(int i=0;i<plan.size();i++){JSONObject row=plan.getJSONObject(i);String k=key(row);BigDecimal quantity=cancel?(filled.add(k)?actual.getOrDefault(k,BigDecimal.ZERO):BigDecimal.ZERO):input.getJSONObject(i).getBigDecimal("quantity");require(quantity!=null&&quantity.signum()>=0&&quantity.scale()<=6&&quantity.precision()-quantity.scale()<=12,"计划数量须为非负数，最多6位小数");row.put("quantity",quantity);totals.put(k,totals.getOrDefault(k,BigDecimal.ZERO).add(quantity));}
  for(Map.Entry<String,BigDecimal> a:actual.entrySet())require(totals.getOrDefault(a.getKey(),BigDecimal.ZERO).compareTo(a.getValue())>=0,"调整后累计计划不能低于该产品工序车间已经记录的产出");
  JSONArray routes=JSON.parseArray(t.get("route_json").toString());Set<String> routeKeys=new HashSet<>();Map<String,BigDecimal> stageTotals=new HashMap<>();for(Object value:routes){JSONObject row=(JSONObject)value;String k=key(row);BigDecimal q=routeKeys.add(k)?totals.getOrDefault(k,BigDecimal.ZERO):BigDecimal.ZERO;row.put("quantity",q);String stage=row.getIntValue("lineNo")+"|"+row.getIntValue("stageNo");stageTotals.put(stage,stageTotals.getOrDefault(stage,BigDecimal.ZERO).add(q));}
  stock.releaseForOrder(head,u,"领导批准后统筹落实订单变更，释放原预留，需仓库重新核查");JSONArray salesLines=JSON.parseArray(o.get("lines_json").toString());BigDecimal total=BigDecimal.ZERO;
  List<Map<String,Object>> items=jdbc.queryForList("SELECT di.id,e.bar_code FROM jsh_depot_item di JOIN jsh_material_extend e ON e.id=di.material_extend_id AND e.tenant_id=di.tenant_id WHERE di.tenant_id=? AND di.header_id=? AND IFNULL(di.delete_flag,'0')='0' ORDER BY di.id FOR UPDATE",u.getTenantId(),head);require(items.size()==salesLines.size(),"原订单库存明细不一致，请核对");
  for(int i=0;i<salesLines.size();i++){JSONObject line=salesLines.getJSONObject(i);require(line.getString("barCode").equals(items.get(i).get("bar_code")),"原订单明细顺序已变化，请核对");BigDecimal qty=after.getJSONArray("lines").getJSONObject(i).getBigDecimal("quantity"),amount=qty.multiply(line.getBigDecimal("price")).setScale(2,RoundingMode.HALF_UP);for(String k:Arrays.asList("quantity","operNumber"))line.put(k,qty);for(String k:Arrays.asList("allPrice","taxLastMoney"))line.put(k,amount);total=total.add(amount);jdbc.update("UPDATE jsh_depot_item SET oper_number=?,basic_number=?,all_price=?,tax_last_money=? WHERE tenant_id=? AND header_id=? AND id=?",qty,qty,amount,amount,u.getTenantId(),head,items.get(i).get("id"));}
  require(total.precision()-total.scale()<=18,"变更后订单金额超过允许范围");jdbc.update("UPDATE jsh_depot_head SET total_price=?,discount_last_money=? WHERE tenant_id=? AND id=?",total,total,u.getTenantId(),head);jdbc.update("UPDATE jsh_factory_sales_order SET delivery_date=?,requirements=?,lines_json=?,workflow_status=?,version=version+1,updated_at=NOW() WHERE tenant_id=? AND head_id=?",after.getString("deliveryDate"),after.getString("requirements"),salesLines.toJSONString(),cancel?"cancelled":"approved",u.getTenantId(),head);
  JSONArray taskLines=JSON.parseArray(t.get("lines_json").toString());for(int i=0;i<taskLines.size();i++){JSONObject line=taskLines.getJSONObject(i);BigDecimal maximum=BigDecimal.ZERO;for(Map.Entry<String,BigDecimal> stage:stageTotals.entrySet())if(stage.getKey().startsWith(i+"|"))maximum=maximum.max(stage.getValue());line.put("productionQuantity",maximum);line.put("quantity",salesLines.getJSONObject(i).getBigDecimal("quantity"));line.put("reserved",BigDecimal.ZERO);line.put("missing",cancel?BigDecimal.ZERO:salesLines.getJSONObject(i).getBigDecimal("quantity"));}
  jdbc.update("UPDATE jsh_factory_production_task SET lines_json=?,plan_json=?,route_json=?,requirements=?,version=version+1,updated_at=NOW() WHERE tenant_id=? AND head_id=?",taskLines.toJSONString(),plan.toJSONString(),routes.toJSONString(),after.getString("requirements"),u.getTenantId(),head);
  JSONObject record=new JSONObject();record.put("beforePlan",oldPlan);record.put("afterPlan",plan);record.put("beforeRoutes",JSON.parseArray(t.get("route_json").toString()));record.put("afterRoutes",routes);record.put("orderChangeId",ch.get("id"));b.put("productionAdjustment",record);
  jdbc.update("UPDATE jsh_factory_order_change SET applied_by=?,applied_at=NOW() WHERE tenant_id=? AND id=?",u.getId(),u.getTenantId(),ch.get("id"));jdbc.update("INSERT INTO jsh_factory_production_history(tenant_id,head_id,action,actor_id,actor_name,comment,payload_json,created_at) VALUES(?,?,'order_change',?,?,?,?,NOW())",u.getTenantId(),head,u.getId(),u.getUsername(),cancel?"统筹确认订单取消并停产；历史产出继续质检入库":"统筹落实订单变更及排班累计数量",record.toJSONString());
 }
 private void audit(User u,long id,String action,String comment,Object payload){jdbc.update("INSERT INTO jsh_factory_order_change_history(tenant_id,change_id,action,actor_name,comment,payload_json,created_at) VALUES(?,?,?,?,?,?,NOW())",u.getTenantId(),id,action,u.getUsername(),comment,JSON.toJSONString(payload));if(id>0)jdbc.update("INSERT INTO jsh_factory_sales_history(tenant_id,head_id,action,actor_id,actor_name,comment,created_at) SELECT tenant_id,head_id,?,?,?, ?,NOW() FROM jsh_factory_order_change WHERE tenant_id=? AND id=?","change_"+action,u.getId(),u.getUsername(),comment,u.getTenantId(),id);}
}
